interface Lst {
    int size(); int get(int i);
    default void print() {
        for (int i = 0; i < size(); i++) System.out.print(get(i) + " ");
        System.out.println();
    }
}
class Arr implements Lst {
    public int size() { return 3; }
    public int get(int i) { return i * i; }
}
new Arr().print();     // 0 1 4  (default method calls Arr's size/get)

interface Greeter {
    default void hello() { System.out.println("Greeter hello"); describe(); }
    void describe();
}
class Animal implements Greeter {
    String name = "animal";
    static String kind() { return "Animal kind"; }
    public void describe() { System.out.println("Animal describe"); }
    void play(Animal a) { System.out.println("Animal plays with Animal"); }
    void play(Dog d)    { System.out.println("Animal plays with Dog"); }
    void meet(Animal a) { System.out.println("Animal meets"); a.describe(); }
}
class Dog extends Animal {
    String name = "dog";
    static String kind() { return "Dog kind"; }
    public void describe() { System.out.println("Dog describe"); }
    void play(Animal a) { System.out.println("Dog plays with Animal"); }
    void play(Puppy p)  { System.out.println("Dog plays with Puppy"); }
    void fetch()        { System.out.println("fetch"); }
}
class Puppy extends Dog {
    public void hello() { System.out.println("Puppy hello"); super.hello(); }
    void play(Dog d)    { System.out.println("Puppy plays with Dog"); }
}
class Cat extends Animal {
    public void describe() { System.out.println("Cat describe"); }
}
