import java.util.function.IntUnaryOperator;
class TenX implements IntUnaryOperator {
    public int applyAsInt(int x) { return 10 * x; }
}
static int doTwice(IntUnaryOperator f, int x) {
    return f.applyAsInt(f.applyAsInt(x));
}
static IntUnaryOperator adder(int n) { return x -> x + n; }   // returns a function

doTwice(new TenX(), 3);     // 300
doTwice(x -> 10 * x, 2);    // 200
doTwice(adder(5), 0);       // 10

