static IntUnaryOperator repeat(IntUnaryOperator f, int n) {
    IntUnaryOperator r = x -> x;                 // identity
    for (int i = 0; i < n; i++) {
        IntUnaryOperator prev = r;               // effectively final copy
        r = x -> f.applyAsInt(prev.applyAsInt(x));
    }
    return r;
}

static <A, B, C> Func<A, C> compose(Func<B, C> f, Func<A, B> g) {
    return new Func<A, C>() {
        public C apply(A x) { return f.apply(g.apply(x)); }
    };
}
